Object.assign(SNIP,{});PRESET_NOTES["l61"]={"Ví dụ: Cộng và tính tổng tiền tố": "sum(5) = bit[5] + bit[4] = 3 + 21 = 24. add(3, 10) sửa bit[3], bit[4], bit[8]: đúng ba ô có đoạn chứa vị trí 3. Sau đó sum(5) = 34.", "Ví dụ: Tổng trên đoạn": "Giống mảng cộng dồn: tổng a[3 … 6] = sum(6) − sum(2) = 31 − 7 = 24. Mỗi lời gọi sum đi qua tối đa log₂ n ô.", "Ví dụ: Ô nào quản lý đoạn nào": "Ô lẻ chỉ giữ chính nó; bit[2] giữ a[1..2], bit[4] giữ a[1..4], bit[6] giữ a[5..6], bit[8] giữ cả a[1..8]. Độ dài đoạn của ô i là bit thấp nhất của i.", "Ví dụ: Đếm nghịch thế": "Cặp nghịch thế: (3,1), (3,1), (3,2), (4,1), (4,2), (5,2): 6 cặp. sum(v) đếm số phần tử đã gặp có giá trị ≤ v, nên j − sum(a[j]) là số phần tử trước j lớn hơn hẳn a[j].", "Lỗi: cập nhật bằng cách gán giá trị mới": "In 20 thay vì 18: cây Fenwick chỉ biết cộng thêm. Muốn gán a[i] = v phải cộng chênh lệch v − a[i] và nhớ cập nhật mảng a của mình: add(2, 10 − a[2]); a[2] = 10."};EX_HINTS["l61"]=[["add(i, x): for (; i <= n; i += i & -i) bit[i] += x;", "sum(i): for (; i > 0; i -= i & -i) s += bit[i]; tổng đoạn = sum(r) − sum(l − 1).", "Tổng tới 2·10^5 · 2·10^9: long long."], ["Nén tọa độ: b = a đã sắp và bỏ trùng; thứ hạng của x là lower_bound(b, x) + 1 (từ 1).", "Duyệt j từ trái sang: số phần tử đứng trước lớn hơn a[j] là j − sum(thứ hạng của a[j]); rồi add(thứ hạng, 1).", "Số nghịch thế tới n²/2 ≈ 2·10^10: long long."], ["Cây Fenwick chỉ có thao tác cộng. Gán a[u] = v tương đương cộng thêm v − a[u].", "Phải giữ riêng mảng a với giá trị hiện tại để biết chênh lệch, và cập nhật a[u] = v sau khi cộng.", "Gán cùng một giá trị hai lần liên tiếp thì lần sau chênh lệch là 0."]];
/* ===================== BÀI 61 · Cây Fenwick (BIT) ===================== */
/* Bài 61 · Cây Fenwick (BIT)
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR61=[{label:"Ví dụ: Cộng và tính tổng tiền tố",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> bit;\n\nvoid add(int i, long long x) {        // a[i] += x\n    for (; i <= n; i += i & -i) bit[i] += x;\n}\n\nlong long sum(int i) {                 // a[1] + … + a[i]\n    long long s = 0;\n    for (; i > 0; i -= i & -i) s += bit[i];\n    return s;\n}\n\nint main() {\n    n = 8;\n    bit.assign(n + 1, 0);\n    int a[9] = {0, 5, 2, 8, 6, 3, 7, 1, 4};\n    for (int i = 1; i <= n; i++) add(i, a[i]);\n    cout << sum(5) << \" \" << sum(8) << \"\\n\";\n    add(3, 10);                        // a[3] = 18\n    cout << sum(5) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"bit",ptr:["i"]},{type:"calls"}],py:{code:"n = 8\nbit = [0] * (n + 1)\n\ndef add(i, x):                         # a[i] += x\n    while i <= n:\n        bit[i] += x\n        i += i & -i\n\ndef tong(i):                           # a[1] + … + a[i]\n    s = 0\n    while i > 0:\n        s += bit[i]\n        i -= i & -i\n    return s\n\na = [0, 5, 2, 8, 6, 3, 7, 1, 4]\nfor i in range(1, n + 1):\n    add(i, a[i])\nprint(tong(5), tong(8))\nadd(3, 10)                             # a[3] = 18\nprint(tong(5))",note:"tong(5) = bit[5] + bit[4] = 3 + 21 = 24. add(3, 10) sửa bit[3], bit[4], bit[8]: đúng ba ô có đoạn chứa vị trí 3. Sau đó tong(5) = 34. (Đặt tên tong để không che hàm sum có sẵn của Python.)"},cs:{code:"using System;\n\nclass Program\n{\n    static int n;\n    static long[] bit;\n\n    static void Add(int i, long x)         // a[i] += x\n    {\n        for (; i <= n; i += i & -i) bit[i] += x;\n    }\n\n    static long Sum(int i)                 // a[1] + … + a[i]\n    {\n        long s = 0;\n        for (; i > 0; i -= i & -i) s += bit[i];\n        return s;\n    }\n\n    static void Main()\n    {\n        n = 8;\n        bit = new long[n + 1];\n        int[] a = { 0, 5, 2, 8, 6, 3, 7, 1, 4 };\n        for (int i = 1; i <= n; i++) Add(i, a[i]);\n        Console.WriteLine(Sum(5) + \" \" + Sum(8));\n        Add(3, 10);                            // a[3] = 18\n        Console.WriteLine(Sum(5));\n    }\n}"}},{label:"Ví dụ: Tổng trên đoạn",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> bit;\n\nvoid add(int i, long long x) {        // a[i] += x\n    for (; i <= n; i += i & -i) bit[i] += x;\n}\n\nlong long sum(int i) {                 // a[1] + … + a[i]\n    long long s = 0;\n    for (; i > 0; i -= i & -i) s += bit[i];\n    return s;\n}\n\nint main() {\n    n = 8;\n    bit.assign(n + 1, 0);\n    int a[9] = {0, 5, 2, 8, 6, 3, 7, 1, 4};\n    for (int i = 1; i <= n; i++) add(i, a[i]);\n    int l = 3, r = 6;\n    cout << sum(r) - sum(l - 1) << \"\\n\";    // a[3] + … + a[6]\n    return 0;\n}",viz:[{type:"cells",of:"bit",ptr:["i"]}],py:{code:"n = 8\nbit = [0] * (n + 1)\n\ndef add(i, x):                         # a[i] += x\n    while i <= n:\n        bit[i] += x\n        i += i & -i\n\ndef tong(i):                           # a[1] + … + a[i]\n    s = 0\n    while i > 0:\n        s += bit[i]\n        i -= i & -i\n    return s\n\na = [0, 5, 2, 8, 6, 3, 7, 1, 4]\nfor i in range(1, n + 1):\n    add(i, a[i])\nl, r = 3, 6\nprint(tong(r) - tong(l - 1))           # a[3] + … + a[6]"},cs:{code:"using System;\n\nclass Program\n{\n    static int n;\n    static long[] bit;\n\n    static void Add(int i, long x)         // a[i] += x\n    {\n        for (; i <= n; i += i & -i) bit[i] += x;\n    }\n\n    static long Sum(int i)                 // a[1] + … + a[i]\n    {\n        long s = 0;\n        for (; i > 0; i -= i & -i) s += bit[i];\n        return s;\n    }\n\n    static void Main()\n    {\n        n = 8;\n        bit = new long[n + 1];\n        int[] a = { 0, 5, 2, 8, 6, 3, 7, 1, 4 };\n        for (int i = 1; i <= n; i++) Add(i, a[i]);\n        int l = 3, r = 6;\n        Console.WriteLine(Sum(r) - Sum(l - 1)); // a[3] + … + a[6]\n    }\n}"}},{label:"Ví dụ: Ô nào quản lý đoạn nào",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n = 8;\n    for (int i = 1; i <= n; i++) {\n        int low = i & -i;              // bit 1 thấp nhất của i\n        cout << \"bit[\" << i << \"] = a[\" << i - low + 1 << \"..\" << i << \"]\\n\";\n    }\n    return 0;\n}",viz:[{type:"vars",names:["i","low"]}],py:{code:"n = 8\nfor i in range(1, n + 1):\n    low = i & -i                       # bit 1 thấp nhất của i\n    print(\"bit[\" + str(i) + \"] = a[\" + str(i - low + 1) + \"..\" + str(i) + \"]\")"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 8;\n        for (int i = 1; i <= n; i++)\n        {\n            int low = i & -i;                  // bit 1 thấp nhất của i\n            Console.WriteLine(\"bit[\" + i + \"] = a[\" + (i - low + 1) + \"..\" + i + \"]\");\n        }\n    }\n}"}},{label:"Ví dụ: Đếm nghịch thế",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> bit;\n\nvoid add(int i, long long x) {        // a[i] += x\n    for (; i <= n; i += i & -i) bit[i] += x;\n}\n\nlong long sum(int i) {                 // a[1] + … + a[i]\n    long long s = 0;\n    for (; i > 0; i -= i & -i) s += bit[i];\n    return s;\n}\n\nint main() {\n    vector<int> a = {3, 1, 4, 1, 5, 2};\n    n = 5;                             // các giá trị nằm trong 1..5\n    bit.assign(n + 1, 0);\n    long long nghich = 0;\n    for (int j = 0; j < (int)a.size(); j++) {\n        nghich += j - sum(a[j]);       // số phần tử đứng trước lớn hơn a[j]\n        add(a[j], 1);                  // ghi nhận đã gặp giá trị a[j]\n    }\n    cout << nghich << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cells",of:"bit"}],py:{code:"a = [3, 1, 4, 1, 5, 2]\nn = 5                                  # các giá trị nằm trong 1..5\nbit = [0] * (n + 1)\n\ndef add(i, x):                         # a[i] += x\n    while i <= n:\n        bit[i] += x\n        i += i & -i\n\ndef tong(i):                           # a[1] + … + a[i]\n    s = 0\n    while i > 0:\n        s += bit[i]\n        i -= i & -i\n    return s\n\nnghich = 0\nfor j in range(len(a)):\n    nghich += j - tong(a[j])           # số phần tử đứng trước lớn hơn a[j]\n    add(a[j], 1)                       # ghi nhận đã gặp giá trị a[j]\nprint(nghich)"},cs:{code:"using System;\n\nclass Program\n{\n    static int n;\n    static long[] bit;\n\n    static void Add(int i, long x)         // a[i] += x\n    {\n        for (; i <= n; i += i & -i) bit[i] += x;\n    }\n\n    static long Sum(int i)                 // a[1] + … + a[i]\n    {\n        long s = 0;\n        for (; i > 0; i -= i & -i) s += bit[i];\n        return s;\n    }\n\n    static void Main()\n    {\n        int[] a = { 3, 1, 4, 1, 5, 2 };\n        n = 5;                                 // các giá trị nằm trong 1..5\n        bit = new long[n + 1];\n        long nghich = 0;\n        for (int j = 0; j < a.Length; j++)\n        {\n            nghich += j - Sum(a[j]);           // số phần tử đứng trước lớn hơn a[j]\n            Add(a[j], 1);                      // ghi nhận đã gặp giá trị a[j]\n        }\n        Console.WriteLine(nghich);\n    }\n}"}},{label:"Lỗi: cập nhật bằng cách gán giá trị mới",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> bit;\n\nvoid add(int i, long long x) {        // a[i] += x\n    for (; i <= n; i += i & -i) bit[i] += x;\n}\n\nlong long sum(int i) {                 // a[1] + … + a[i]\n    long long s = 0;\n    for (; i > 0; i -= i & -i) s += bit[i];\n    return s;\n}\n\nint main() {\n    n = 4;\n    bit.assign(n + 1, 0);\n    int a[5] = {0, 1, 2, 3, 4};\n    for (int i = 1; i <= n; i++) add(i, a[i]);\n    // muốn đổi a[2] thành 10\n    add(2, 10);                        // SAI: cộng 10, không phải cộng 10 - a[2]\n    cout << sum(4) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"bit",ptr:["i"]}],py:{code:"n = 4\nbit = [0] * (n + 1)\n\ndef add(i, x):                         # a[i] += x\n    while i <= n:\n        bit[i] += x\n        i += i & -i\n\ndef tong(i):                           # a[1] + … + a[i]\n    s = 0\n    while i > 0:\n        s += bit[i]\n        i -= i & -i\n    return s\n\na = [0, 1, 2, 3, 4]\nfor i in range(1, n + 1):\n    add(i, a[i])\n# muốn đổi a[2] thành 10\nadd(2, 10)                             # SAI: cộng 10, không phải cộng 10 - a[2]\nprint(tong(4))"},cs:{code:"using System;\n\nclass Program\n{\n    static int n;\n    static long[] bit;\n\n    static void Add(int i, long x)         // a[i] += x\n    {\n        for (; i <= n; i += i & -i) bit[i] += x;\n    }\n\n    static long Sum(int i)                 // a[1] + … + a[i]\n    {\n        long s = 0;\n        for (; i > 0; i -= i & -i) s += bit[i];\n        return s;\n    }\n\n    static void Main()\n    {\n        n = 4;\n        bit = new long[n + 1];\n        int[] a = { 0, 1, 2, 3, 4 };\n        for (int i = 1; i <= n; i++) Add(i, a[i]);\n        // muốn đổi a[2] thành 10\n        Add(2, 10);                            // SAI: cộng 10, không phải cộng 10 - a[2]\n        Console.WriteLine(Sum(4));\n    }\n}"}}];
