makeEx2(document.getElementById("ex-l61"),sim61,[{t:"Sổ quỹ",d:"Sổ quỹ có n mục a₁ … aₙ. Có q thao tác: “1 i x” cộng x vào mục i; “2 l r” hỏi tổng các mục l … r. Đầu vào: n q (1 ≤ n, q ≤ 2·10^5), dòng a₁ … aₙ (|aᵢ| ≤ 10^9), rồi q dòng thao tác (|x| ≤ 10^9). Đầu ra: đáp án của mỗi thao tác loại 2, mỗi dòng một số.",tests:[{in:"8 6\n5 2 8 6 3 7 1 4\n2 1 5\n1 3 10\n2 1 5\n2 3 6\n1 8 -4\n2 8 8",out:"24\n34\n34\n0"},{in:"1 3\n7\n2 1 1\n1 1 -7\n2 1 1",out:"7\n0"},{in:"3 2\n1000000000 1000000000 1000000000\n1 2 1000000000\n2 1 3",out:"4000000000"},{in:"30 40\n26 -54 42 -45 -18 -25 -18 77 -93 24 -9 -9 -84 3 18 -16 -58 -15 61 -99 28 76 -77 62 -56 -14 -94 10 -64 -68\n2 10 19\n2 28 29\n1 11 58\n1 27 60\n2 26 30\n1 14 -41\n1 2 38\n1 1 38\n1 28 -22\n2 14 19\n1 12 82\n1 7 -71\n2 20 25\n1 16 -32\n1 13 -51\n1 13 26\n1 22 -22\n2 21 27\n1 28 -6\n2 24 26\n2 29 29\n2 28 30\n1 15 -81\n2 23 26\n2 6 9\n2 24 27\n1 7 -33\n2 19 26\n1 16 -81\n1 8 -54\n1 13 17\n1 29 -61\n2 3 30\n2 5 9\n1 5 -57\n1 3 8\n1 8 11\n1 30 74\n2 26 30\n2 25 25",out:"-85\n-54\n-170\n-48\n-66\n-37\n-8\n-64\n-150\n-85\n-130\n-42\n-41\n-773\n-235\n-185\n-56"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> bit;\n\nvoid add(int i, long long x) {\n    // cộng x vào bit[i] và các ô phía sau: i += i & -i\n}\n\nlong long sum(int i) {\n    long long s = 0;\n    // cộng bit[i] rồi i -= i & -i\n    return s;\n}\n\nint main() {\n    int q;\n    cin >> n >> q;\n    bit.assign(n + 1, 0);\n    for (int i = 1; i <= n; i++) {\n        long long x;\n        cin >> x;\n        add(i, x);\n    }\n    for (int t = 0; t < q; t++) {\n        long long k, u, v;\n        cin >> k >> u >> v;\n        if (k == 1) add(u, v);\n        else cout << sum(v) - sum(u - 1) << \"\\n\";\n    }\n    return 0;\n}",perf:{gen:n=>{const a=Array.from({length:n},(_,i)=>(i*7919)%1000);const q=[];for(let i=0;i<n;i++){if(i%2)q.push("1 "+(1+(i*13)%n)+" "+(i%50));else{const l=1+(i*7)%Math.max(1,Math.floor(n/4));q.push("2 "+l+" "+Math.min(n,l+Math.floor(n/2)))}}return n+" "+n+"\n"+a.join(" ")+"\n"+q.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>100*n*Math.log2(n)+300,why:"Cộng thẳng vào mảng rồi duyệt cả đoạn cho mỗi câu hỏi tổng tốn O(n) mỗi câu."},py:{start:"n, q = map(int, input().split())\na = [0] + list(map(int, input().split()))\nbit = [0] * (n + 1)\n\ndef add(i, x):\n    pass                               # cộng x vào bit[i] và các ô phía sau: i += i & -i\n\ndef tong(i):\n    s = 0\n    # cộng bit[i] rồi i -= i & -i\n    return s\n\nfor i in range(1, n + 1):\n    add(i, a[i])\nout = []\nfor _ in range(q):\n    k, u, v = map(int, input().split())\n    if k == 1:\n        add(u, v)\n    else:\n        out.append(tong(v) - tong(u - 1))\nprint(\"\\n\".join(map(str, out)))",hints:["add(i, x): while i <= n: bit[i] += x; i += i & -i","tong(i): while i > 0: s += bit[i]; i -= i & -i. Tổng đoạn = tong(r) − tong(l − 1).","Gom kết quả vào list rồi in một lần."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static long[] bit;\n\n    static void Add(int i, long x)\n    {\n        // cộng x vào bit[i] và các ô phía sau: i += i & -i\n    }\n\n    static long Sum(int i)\n    {\n        long s = 0;\n        // cộng bit[i] rồi i -= i & -i\n        return s;\n    }\n\n    static void Main()\n    {\n        int[] nq = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        n = nq[0];\n        int q = nq[1];\n        long[] a = Array.ConvertAll((\"0 \" + Console.ReadLine()).Split(), long.Parse);\n        bit = new long[n + 1];\n        for (int i = 1; i <= n; i++) Add(i, a[i]);\n        var sb = new StringBuilder();\n        for (int t = 0; t < q; t++)\n        {\n            long[] c = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            int u = (int)c[1];\n            if (c[0] == 1)\n            {\n                Add(u, c[2]);\n            }\n            else sb.Append(Sum((int)c[2]) - Sum(u - 1)).Append('\\n');\n        }\n        Console.Write(sb.ToString());\n    }\n}",hints:["Add(i, x): for (; i <= n; i += i & -i) bit[i] += x;","Sum(i): for (; i > 0; i -= i & -i) s += bit[i]; tổng đoạn = Sum(r) − Sum(l − 1).","Tổng tới 2·10^5 · 2·10^9: long."]}},{t:"Đếm nghịch thế",d:"Đầu vào: n (1 ≤ n ≤ 2·10^5) và n số nguyên (|aᵢ| ≤ 10^9, có thể trùng). Đầu ra: số cặp (i, j) với i < j và aᵢ > aⱼ.",tests:[{in:"6\n3 1 4 1 5 2",out:"6"},{in:"3\n1 2 3",out:"0"},{in:"3\n3 2 1",out:"3"},{in:"3\n5 5 5",out:"0"},{in:"3\n1000000000 -1000000000 0",out:"2"},{in:"60\n-33 16 34 -7 47 12 -25 14 -34 37 32 23 27 -45 -44 12 -6 6 -9 49 36 18 -15 10 38 -14 -33 21 -15 33 18 28 34 -33 30 -6 -11 -27 38 23 -28 -18 24 3 48 -36 -31 15 49 -32 12 38 -16 44 48 7 -37 22 35 24",out:"834"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> bit;\n\nvoid add(int i, long long x) {\n    for (; i <= n; i += i & -i) bit[i] += x;\n}\n\nlong long sum(int i) {\n    long long s = 0;\n    for (; i > 0; i -= i & -i) s += bit[i];\n    return s;\n}\n\nint main() {\n    cin >> n;\n    vector<int> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // nén tọa độ: thay a[i] bằng thứ hạng 1..k trong mảng đã sắp, bỏ trùng\n    bit.assign(n + 1, 0);\n    long long nghich = 0;\n    cout << nghich << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919+13)%1000000007).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>120*n*Math.log2(n)+300,why:"Xét mọi cặp tốn O(n²)."},py:{start:"n = int(input())\na = list(map(int, input().split()))\nbit = [0] * (n + 1)\n\ndef add(i, x):                         # a[i] += x\n    while i <= n:\n        bit[i] += x\n        i += i & -i\n\ndef tong(i):                           # a[1] + … + a[i]\n    s = 0\n    while i > 0:\n        s += bit[i]\n        i -= i & -i\n    return s\n\n# nén tọa độ: thay a[i] bằng thứ hạng 1..k trong mảng đã sắp, bỏ trùng\nnghich = 0\nprint(nghich)",hints:["Nén tọa độ: hang = {v: i + 1 for i, v in enumerate(sorted(set(a)))}.","Duyệt j từ trái sang: số phần tử đứng trước lớn hơn a[j] là j − tong(hang[a[j]]); rồi add(hang[a[j]], 1).","Hai vòng lặp lồng nhau xét mọi cặp là O(n²)."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static long[] bit;\n\n    static void Add(int i, long x)         // a[i] += x\n    {\n        for (; i <= n; i += i & -i) bit[i] += x;\n    }\n\n    static long Sum(int i)                 // a[1] + … + a[i]\n    {\n        long s = 0;\n        for (; i > 0; i -= i & -i) s += bit[i];\n        return s;\n    }\n\n    static void Main()\n    {\n        n = int.Parse(Console.ReadLine());\n        int[] a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        bit = new long[n + 1];\n        // nén tọa độ: thay a[i] bằng thứ hạng 1..k trong mảng đã sắp, bỏ trùng\n        long nghich = 0;\n        Console.WriteLine(nghich);\n    }\n}",hints:["Nén tọa độ: sắp một bản sao, gán thứ hạng 1, 2, … cho từng giá trị khác nhau (Dictionary).","Duyệt j từ trái sang: số phần tử đứng trước lớn hơn a[j] là j − Sum(thứ hạng của a[j]); rồi Add(thứ hạng, 1).","Số nghịch thế tới n²/2: long."]}},{t:"Bảng điểm sửa liên tục",d:"n học sinh có điểm a₁ … aₙ. Thao tác “1 i v”: điểm của học sinh i thành v (gán, không phải cộng); “2 l r”: tổng điểm các học sinh l … r. Đầu vào: n q (1 ≤ n, q ≤ 2·10^5), dòng a₁ … aₙ (0 ≤ aᵢ ≤ 10^9), rồi q dòng (0 ≤ v ≤ 10^9). Đầu ra: đáp án các thao tác loại 2.",tests:[{in:"4 4\n1 2 3 4\n1 2 10\n2 1 4\n1 2 10\n2 2 2",out:"18\n10"},{in:"1 3\n5\n2 1 1\n1 1 0\n2 1 1",out:"5\n0"},{in:"3 3\n0 0 0\n1 1 1000000000\n1 3 1000000000\n2 1 3",out:"2000000000"},{in:"30 40\n370 106 627 387 519 489 286 217 210 382 840 711 467 128 290 661 606 835 786 868 91 476 469 953 155 653 786 528 46 194\n2 18 26\n2 18 22\n1 10 174\n1 20 610\n2 30 30\n1 16 803\n1 13 3\n2 10 15\n1 9 596\n1 20 624\n2 22 25\n1 6 57\n2 11 20\n1 4 382\n2 19 25\n2 26 28\n1 20 216\n2 26 29\n1 30 80\n1 11 160\n2 13 15\n1 3 818\n1 7 651\n1 30 834\n2 24 26\n1 7 919\n2 21 28\n1 4 975\n2 25 29\n1 27 850\n2 1 19\n1 27 129\n2 5 27\n2 16 29\n2 10 10\n1 8 318\n2 24 25\n2 1 27\n1 21 204\n2 21 23",out:"5286\n3056\n194\n2146\n2053\n5626\n3554\n1967\n2013\n421\n1761\n4111\n2168\n9073\n9946\n6746\n174\n1108\n12316\n1149"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint n;\nvector<long long> bit, a;\n\nvoid add(int i, long long x) {\n    for (; i <= n; i += i & -i) bit[i] += x;\n}\n\nlong long sum(int i) {\n    long long s = 0;\n    for (; i > 0; i -= i & -i) s += bit[i];\n    return s;\n}\n\nint main() {\n    int q;\n    cin >> n >> q;\n    bit.assign(n + 1, 0);\n    a.assign(n + 1, 0);\n    for (int i = 1; i <= n; i++) {\n        cin >> a[i];\n        add(i, a[i]);\n    }\n    for (int t = 0; t < q; t++) {\n        long long k, u, v;\n        cin >> k >> u >> v;\n        if (k == 1) {\n            // gán a[u] = v: cây chỉ biết cộng, nên cộng phần chênh lệch\n        } else {\n            cout << sum(v) - sum(u - 1) << \"\\n\";\n        }\n    }\n    return 0;\n}",perf:{gen:n=>{const a=Array.from({length:n},(_,i)=>(i*7919)%1000);const q=[];for(let i=0;i<n;i++){if(i%2)q.push("1 "+(1+(i*13)%n)+" "+(i%500));else{const l=1+(i*7)%Math.max(1,Math.floor(n/4));q.push("2 "+l+" "+Math.min(n,l+Math.floor(n/2)))}}return n+" "+n+"\n"+a.join(" ")+"\n"+q.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>100*n*Math.log2(n)+300,why:"Gán thẳng vào mảng rồi duyệt cả đoạn cho mỗi câu hỏi tổng tốn O(n) mỗi câu."},py:{start:"n, q = map(int, input().split())\na = [0] + list(map(int, input().split()))\nbit = [0] * (n + 1)\n\ndef add(i, x):                         # a[i] += x\n    while i <= n:\n        bit[i] += x\n        i += i & -i\n\ndef tong(i):                           # a[1] + … + a[i]\n    s = 0\n    while i > 0:\n        s += bit[i]\n        i -= i & -i\n    return s\n\nfor i in range(1, n + 1):\n    add(i, a[i])\nout = []\nfor _ in range(q):\n    k, u, v = map(int, input().split())\n    if k == 1:\n        pass                       # gán a[u] = v: cây chỉ biết cộng, nên cộng phần chênh lệch\n    else:\n        out.append(tong(v) - tong(u - 1))\nprint(\"\\n\".join(map(str, out)))",hints:["Cây Fenwick chỉ có thao tác cộng. Gán a[u] = v tương đương cộng thêm v − a[u].","Phải giữ riêng mảng a với giá trị hiện tại để biết chênh lệch, và cập nhật a[u] = v sau khi cộng.","Gán cùng một giá trị hai lần liên tiếp thì lần sau chênh lệch là 0."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static int n;\n    static long[] bit;\n\n    static void Add(int i, long x)         // a[i] += x\n    {\n        for (; i <= n; i += i & -i) bit[i] += x;\n    }\n\n    static long Sum(int i)                 // a[1] + … + a[i]\n    {\n        long s = 0;\n        for (; i > 0; i -= i & -i) s += bit[i];\n        return s;\n    }\n\n    static void Main()\n    {\n        int[] nq = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        n = nq[0];\n        int q = nq[1];\n        long[] a = Array.ConvertAll((\"0 \" + Console.ReadLine()).Split(), long.Parse);\n        bit = new long[n + 1];\n        for (int i = 1; i <= n; i++) Add(i, a[i]);\n        var sb = new StringBuilder();\n        for (int t = 0; t < q; t++)\n        {\n            long[] c = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            int u = (int)c[1];\n            if (c[0] == 1)\n            {\n                // gán a[u] = c[2]: cây chỉ biết cộng, nên cộng phần chênh lệch\n            }\n            else sb.Append(Sum((int)c[2]) - Sum(u - 1)).Append('\\n');\n        }\n        Console.Write(sb.ToString());\n    }\n}",hints:["Cây Fenwick chỉ có thao tác cộng. Gán a[u] = v tương đương cộng thêm v − a[u].","Phải giữ riêng mảng a với giá trị hiện tại để biết chênh lệch, và cập nhật a[u] = v sau khi cộng.","Gán cùng một giá trị hai lần liên tiếp thì lần sau chênh lệch là 0."]}}]);

